 if(choice.trim()==='5'){try{const a=await api('/api/job/frame/anchor',{id:j.id,which});toast('색 기준으로 지정했습니다: '+a.label)}catch(e){toast(e.message)}return}
 if(choice.trim()==='4'){try{const ref=await api('/api/job/frame/adopt',{id:j.id,which,correct:true,color:S.render.color||{}});S.refs.push(ref);changed();renderRefs();renderShots();toast('색 보정 후 레퍼런스로 추가했습니다.'+String.fromCharCode(10)+ref.note)}catch(e){toast(e.message)}return}
 if(choice.trim()==='3'){window.open('/api/job/frame?'+new URLSearchParams({id:j.id,which}),'_blank');return}
