 const run=d.run||{},clips=d.clips||[],done=clips.filter(c=>c.done).length,busy=['running','stopping'].includes(run.state)&&run.name===selectedProject;
 box.append(node('p',`저화질 클립 ${clips.length}개 · 고화질 완료 ${done}개 · 결과 프로젝트 ${d.target||''}`,'hint'));
