 const bar=node('div',null,'actions');
 const go=node('button','승인된 클립 전부 고화질로 마감','primary');go.disabled=busy||!clips.length||!!d.missing?.length||!d.pending?.length;
 action(go,async()=>{await api('/api/finish/start',{name:selectedProject});toast('고화질 마감을 시작했습니다.');await renderFinish();pollFinish()});
 const halt=node('button','중지');halt.disabled=!busy;action(halt,async()=>{await api('/api/finish/stop',{});await renderFinish()});
