async function init(){hideProjectTab();try{const [catalog,saved,status]=await Promise.all([api('/api/catalog'),api('/api/state'),api('/api/status')]);C=catalog;if(Object.keys(saved).length){S={...S,...saved,render:{...S.render,...saved.render}}}S.render.chain??=!!S.render.project;delete S.render.checkpoint;S.settings={...C.settings_defaults,dialogue_language:'Japanese',...S.settings};S.render.color??={enabled:false};S.render.turbo??={};S.render.loras??=[];S.render.advanced??={};for(const m of status.ollama.data?.models||[]){const o=node('option',m.name);o.value=m.name;$('#llm').append(o)}$('#llm').prepend(new Option('모델 선택',''));$('#llm').value=S.writer.model||'';$('#llm').onchange=e=>{S.writer.model=e.target.value;changed()};clear($('#services'));for(const [name,key] of [['ComfyUI','comfy'],['Ollama','ollama']]){const p=node('div'),dot=node('span',null,'dot'+(status[key].ok?' ok':''));p.append(dot,document.createTextNode(name+(status[key].ok?' 연결됨':' 연결 확인 필요')));$('#services').append(p)}S.cards.forEach(c=>{c.acts=(c.acts||[]).filter(a=>a.act||a.a||a.b);c.lines=(c.lines||[]).filter(l=>(l.text||'').trim())});renderRefs();renderSettings();renderShots();renderProduction();await assetProjects();await loadRenderProjects();$('#prompt').value=S.prompt;$('#undo').disabled=!S.previous;$('#footer-status').textContent='연결 완료 · 작업 준비됨';await jobs()}catch(e){$('#footer-status').textContent='연결 확인 필요';toast(e.message)}}init();

function previewRef(r,name){const d=node('dialog',null,'media-dialog'),close=node('button','닫기');close.onclick=()=>d.close();const media=node(r.type==='image'?'img':r.type==='audio'?'audio':'video'),meta=node('p',r.type==='image'?'이미지 정보 확인 중…':'','hint');if(r.type==='image'){media.onload=()=>{const w=media.naturalWidth,h=media.naturalHeight;const gcd=(a,b)=>b?gcd(b,a%b):a,g=gcd(w,h);const ratios=['1:1','16:9','9:16','2:1','1:2','3:2','2:3','4:3','3:4','4:5','5:4'];const nearest=ratios.map(label=>{const [a,b]=label.split(':').map(Number);return {label,error:Math.abs(Math.log((w/h)/(a/b)))}}).sort((a,b)=>a.error-b.error)[0];meta.textContent=`해상도 ${w} × ${h} px · 비율 ${nearest.error<.035?(nearest.error>.0001?'약 ':'')+nearest.label:'사용자 비율 '+(w/h).toFixed(2)+':1'}`};media.onerror=()=>meta.textContent='이미지를 불러올 수 없습니다.'}else media.controls=true;media.src='/api/media?file='+encodeURIComponent(r.file);d.append(node('h3',name+' · '+r.name),meta,media,close);d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal()}

async function assetProjects(){const d=await api('/api/asset-projects'),sel=$('#asset-project');clear(sel);sel.append(new Option('프로젝트 선택',''));for(const p of d.projects)sel.append(userOption(p.name,p.id));sel.value=S.asset_project||'';sel.onchange=async()=>{S.asset_project=sel.value;changed();if(!$('#library').hidden)await renderLibrary()}}
action($('#new-asset-project'),async()=>{const name=$('#asset-project-name').value.trim();if(!name)throw Error('프로젝트 이름을 입력하세요.');const d=await api('/api/asset-projects',{name});S.asset_project=d.id;changed();await assetProjects();$('#asset-project-name').value='';$('#library').hidden=false;await renderLibrary()});
async function renderLibrary(){const box=$('#library');clear(box);box.append(node('h2','프로젝트 에셋'));if(!S.asset_project){box.append(node('p','프로젝트를 만들거나 선택하세요.','hint'));return}const d=await api('/api/library?project='+encodeURIComponent(S.asset_project));const grid=node('div',null,'asset-grid');for(const a of d.items){const card=node('article',null,'asset-card');if(a.type==='image'){const img=node('img');img.src='/api/asset-media?project='+encodeURIComponent(S.asset_project)+'&id='+encodeURIComponent(a.id);img.alt=a.name;img.loading='lazy';card.append(img)}card.append(node('strong',a.name),node('small',a.role_label||a.type));const b=node('button','레퍼런스로 추가');action(b,async()=>{const r=await api('/api/library/use',{project:S.asset_project,id:a.id});S.refs.push(r);changed();renderRefs();renderShots();toast('레퍼런스에 추가했습니다.')});card.append(b);const remove=node('button','에셋 삭제','danger');action(remove,async()=>{if(!uiConfirm(`${a.name} 에셋을 휴지통으로 옮길까요? 이미 추가한 레퍼런스는 유지됩니다.`))return;await api('/api/delete/asset',{project:S.asset_project,id:a.id});await renderLibrary();toast('에셋을 휴지통으로 옮겼습니다.')});card.append(remove);grid.append(card)}box.append(grid);if(!d.items.length)box.append(node('p','레퍼런스 카드의 보관 버튼으로 이 프로젝트에 에셋을 추가하세요.','hint'));const old=node('details');old.append(node('summary','기존 공용 보관함에서 가져오기'));old.addEventListener('toggle',async()=>{if(!old.open||old.dataset.loaded)return;try{const legacy=await api('/api/library');for(const a of legacy.items){const b=node('button',a.name||a.id);action(b,async()=>{await api('/api/library/import',{project:S.asset_project,kind:a.kind,id:a.id});await renderLibrary();toast('기존 에셋을 프로젝트에 복사했습니다.')});old.append(b)}old.dataset.loaded='1'}catch(e){toast(e.message)}});box.append(old)}

