function resolutionValues(){const r=S.render;if(r.resolution_mode!=='preset')return;let aspect=r.aspect||'16:9';if(aspect==='auto')aspect=r.source_aspect||'16:9';const [a,b]=aspect.split(':').map(Number);if(!(a>0&&b>0))return;const px=(resolutionPresets[r.resolution_preset]||.52)*1024*1024,h=Math.sqrt(px/(a/b));r.width=Math.max(32,Math.round(h*a/b/32)*32);r.height=Math.max(32,Math.round(h/32)*32)}
function renderResolution(){const r=S.render;r.aspect??='16:9';r.resolution_preset??='0.52 MP - SD';let box=$('#resolution-controls');if(!box){box=node('div',null,'panel');box.id='resolution-controls';$('#render-settings').closest('.panel').after(box)}clear(box);box.append(node('h2','화면 비율 · 해상도'));const g=node('div',null,'form-grid');g.append(field('입력 방식',r,'resolution_mode',[[['manual','직접 입력 (Manual)'],['preset','비율 + 프리셋']]],{onchange:()=>{resolutionValues();renderResolution();summary()}}));if(r.resolution_mode==='preset'){g.append(field('화면 비율',r,'aspect',[[['auto','이미지 1 비율'],...['1:1','16:9','9:16','2:1','1:2','3:2','2:3','4:3','3:4','4:5','5:4'].map(x=>[x,x])]],{onchange:()=>{resolutionValues();renderResolution();summary()}}),field('해상도 프리셋',r,'resolution_preset',[Object.keys(resolutionPresets)],{onchange:()=>{resolutionValues();renderResolution();summary()}}));resolutionValues();const first=S.refs.find(x=>x.enabled!==false&&x.type==='image');if(r.aspect==='auto'&&first){const im=new Image();im.onload=()=>{const ratio=im.naturalWidth+':'+im.naturalHeight;if(r.source_aspect!==ratio){r.source_aspect=ratio;resolutionValues();renderResolution();changed()}};im.src='/api/media?file='+encodeURIComponent(first.file)}g.append(node('p',`${r.width} × ${r.height} px · 모델 규칙에 맞춰 32 단위로 조정`,'hint'))}else g.append(field('가로',r,'width',['INT',{min:32,step:32}]),field('세로',r,'height',['INT',{min:32,step:32}]));box.append(g)}
