function renderKillOptions(){S.kill_options??={comfy_models:true,isolated_workers:true,orphan_workers:false,ollama:true,node_cache:false,torch_cache:true};let box=$('#kill-options');if(!box){box=node('details');box.id='kill-options';$('#kill-switch').before(box)}clear(box);box.append(node('summary','Kill Switch 옵션'));const auto=node('div',null,'toggle');auto.append(field('모든 작업 전에 자동 실행',S.kill_options,'before_every_task',['BOOLEAN',{default:true}]),node('small','영상 · 레퍼런스 이미지 · LLM 작업이 시작될 때 아래 설정으로 먼저 정리합니다. LLM 작업 때는 곧 쓸 Ollama 모델은 내리지 않습니다.'));box.append(auto);const grid=node('div',null,'form-grid');for(const [key,label] of [['comfy_models','ComfyUI 모델'],['isolated_workers','격리 워커'],['orphan_workers','고아 워커'],['ollama','Ollama 모델'],['node_cache','노드 출력 캐시 삭제'],['torch_cache','Torch 캐시']])grid.append(field(label,S.kill_options,key,['BOOLEAN']));box.append(grid,node('p','노드 출력 캐시 삭제를 켜면 이전 베이스 결과도 사라집니다. 업스케일만 이어 실행하려면 끄세요.','hint'))}

async function renderInbox(projectList){
 const box=$('#project-inbox');
 let list=await api('/api/jobs');
 for(const j of list)if(['queued','running','unknown'].includes(j.state)&&!j.settings?.maintenance)poll(j.id);
 list=list.filter(j=>j.state==='completed'&&(j.outputs||[]).some(o=>/\.(mp4|webm|mov)$/i.test(o.filename))).sort((a,b)=>b.created-a.created);
 const signature=JSON.stringify([list.map(j=>[j.id,j.saved_project]),projectList]);if(box.dataset.signature===signature)return;box.dataset.signature=signature;
 clear(box);box.append(node('h2','최신 생성 영상'),node('p','프로젝트를 선택하지 않고 생성해도 여기에 표시됩니다. 확인한 뒤 원하는 프로젝트에 저장하세요.','hint'));
 if(!list.length){box.append(node('p','아직 완료된 영상이 없습니다.','empty'));return}
 for(const [i,j] of list.slice(0,10).entries()){
  const item=node(i?'details':'div',null,'job');if(i)item.append(node('summary',new Date(j.created*1000).toLocaleString(uiLocale())));else item.append(node('h3',new Date(j.created*1000).toLocaleString(uiLocale())));
  const o=j.outputs.find(o=>/\.(mp4|webm|mov)$/i.test(o.filename));const v=node('video');v.controls=true;v.preload='metadata';v.src=o.url;v.style.cssText='width:100%;max-height:360px;object-fit:contain';item.append(v);
  const row=node('div',null,'actions');const download=node('a','영상 다운로드');download.href=o.url;download.download=o.filename;row.append(download);
  const remove=node('button','생성 결과 삭제','danger');action(remove,()=>deleteResult(j));row.append(remove);const current=j.saved_project?.name||j.settings?.project;
  if(current){const open=node('button','저장된 프로젝트: '+current);action(open,()=>openProject(current));row.append(open)}
  else {
   const select=node('select');select.append(new Option('저장할 프로젝트 선택',''));for(const p of projectList){const n=typeof p==='string'?p:p.name||p.project_name;select.append(userOption(n,n))}select.value=selectedProject||'';
   const saveButton=node('button','프로젝트에 저장','primary');action(saveButton,async()=>{if(!select.value)throw Error('저장할 프로젝트를 선택하세요. 없으면 아래에서 먼저 만드세요.');const result=await api('/api/inbox/save',{job_id:j.id,name:select.value});toast(result.kind==='clip'?'이어 만들기 가능한 클립으로 저장했습니다.':'영상 파일로 보관했습니다.');await projects();await openProject(result.name)});row.append(select,saveButton);
   item.append(node('small',j.settings?._draft_project?'이어받기 데이터 포함 · 저장하면 사용할 클립으로 선택됩니다.':'기존 영상 · 이어받기 데이터가 없어 영상 파일로 보관됩니다.','hint'));
  }
  item.append(row);box.append(item);
 }
}
setInterval(()=>{if(document.visibilityState==='visible'&&$('#projects')?.classList.contains('active')){projects();if(selectedProject)openProject(selectedProject,true).catch(e=>toast(e.message))}},5000);

async function projectDeleted(name){if(selectedProject===name){selectedProject='';projectSignature='';clear($('#project-detail'));$('#project-detail').textContent='프로젝트를 선택하세요.'}if(S.render.project===name){S.render.project='';S.render.chain=false;S.render.candidate_retry=false;changed()}if(S.lastExport?.name===name){delete S.lastExport;changed()}await projects();await loadRenderProjects()}
async function deleteResult(j){if(!uiConfirm('이 생성 결과를 휴지통으로 옮길까요? 프로젝트에 별도로 저장한 클립은 유지됩니다.'))return;document.querySelectorAll('video').forEach(v=>{v.pause();v.removeAttribute('src');v.load()});await api('/api/delete/job',{id:j.id});await jobs();$('#project-inbox').dataset.signature='';await projects();toast('생성 결과를 휴지통으로 옮겼습니다.')}
async function openTrash(){let dialog=$('#trash-dialog');if(!dialog){dialog=node('dialog');dialog.id='trash-dialog';document.body.append(dialog)}clear(dialog);const heading=node('div',null,'actions');heading.append(node('h2','휴지통'));const close=node('button','닫기');close.onclick=()=>dialog.close();heading.append(close);dialog.append(heading,node('p','파일을 보관하므로 디스크 용량은 유지됩니다. 삭제 뒤 같은 프로젝트를 변경했다면 충돌 방지를 위해 복구가 제한될 수 있습니다.','hint'));const data=await api('/api/trash');for(const item of data.items){const row=node('div',null,'trash-row');row.append(node('strong',item.label),node('small',new Date(item.created*1000).toLocaleString(uiLocale())));const restore=node('button','복구');action(restore,async()=>{await api('/api/trash/restore',{id:item.id});await assetProjects();if(!$('#library').hidden&&S.asset_project)await renderLibrary();await jobs();await projects();await loadRenderProjects();if(selectedProject)await openProject(selectedProject);await openTrash();toast('복구했습니다.')});row.append(restore);dialog.append(row)}if(!data.items.length)dialog.append(node('p','휴지통이 비어 있습니다.'));if(!dialog.open)dialog.showModal()}
const trashButton=node('button','휴지통');action(trashButton,openTrash);$('#refresh-projects').after(trashButton);
const assetTrash=node('button','휴지통');action(assetTrash,openTrash);$('#new-asset-project').after(assetTrash);
const deleteAssetProject=node('button','에셋 프로젝트 삭제','danger');action(deleteAssetProject,async()=>{if(!S.asset_project)throw Error('에셋 프로젝트를 선택하세요.');if(!uiConfirm('선택한 에셋 프로젝트와 보관 에셋을 휴지통으로 옮길까요?'))return;await api('/api/delete/asset-project',{project:S.asset_project});S.asset_project='';changed();await assetProjects();await renderLibrary();toast('에셋 프로젝트를 휴지통으로 옮겼습니다.')});assetTrash.after(deleteAssetProject);

// ── LLM 대화 창 ─────────────────────────────────────────────────────────────
// Conversational editing: every reply may carry a whole revised prompt, which is
// only applied when the user presses Apply. Sessions are stored on the server.
let chatId='';
function renderChatSettings(){
 const fresh=!S.chat_llm;
 S.chat_llm={model:S.writer.model||'',temperature:.3,num_ctx:25600,num_predict:-1,history_turns:6,think:false,...S.chat_llm};
 let box=$('#chat-llm-settings');if(!box){box=node('details',null,'chat-llm-settings');box.id='chat-llm-settings';$('#chat-log').before(box)}
 const opened=box.open;clear(box);box.open=opened;
 box.append(node('summary','대화 전용 LLM 설정'),node('p','프롬프트 작성기와 별도로 저장됩니다. 처음 모델만 가져오며, 이후에는 서로 영향을 주지 않습니다.','hint'));
 const options=[['','모델 선택'],...[...$('#llm').options].filter(o=>o.value).map(o=>[o.value,o.value])];
 if(S.chat_llm.model&&!options.some(o=>o[0]===S.chat_llm.model))options.push([S.chat_llm.model,S.chat_llm.model]);
 const grid=node('div',null,'form-grid');
 grid.append(field('대화 모델',S.chat_llm,'model',[options]),
  field('응답 다양성 (temperature)',S.chat_llm,'temperature',['FLOAT',{min:0,max:2,step:.05}]),
  field('문맥 길이 (토큰)',S.chat_llm,'num_ctx',['INT',{min:2048,max:131072,step:1024}]),
  field('최대 응답 토큰 (-1: 제한 없음)',S.chat_llm,'num_predict',['INT',{min:-1,max:32768,step:1}]),
  field('기억할 이전 대화 (턴)',S.chat_llm,'history_turns',['INT',{min:0,max:30,step:1}]));
 box.append(grid,node('p','문맥 길이에는 현재 프롬프트·규칙·이전 대화가 함께 들어갑니다. 크게 설정하면 메모리 사용량이 늘 수 있습니다.','hint'));
 const think=$('#chat-think');think.checked=S.chat_llm.think;think.onchange=()=>{S.chat_llm.think=think.checked;changed()};
 if(fresh)changed();
}

async function chatList(){const list=await api('/api/chats');const box=$('#chat-list');clear(box);
 for(const c of list){const b=node('button',null,'chat-item'+(c.id===chatId?' on':''));b.append(node('strong',c.title||'새 대화'),node('small',`${c.turns}턴 · ${new Date(c.updated*1000).toLocaleString(uiLocale())}`));b.onclick=()=>chatOpen(c.id);box.append(b)}
 if(!list.length)box.append(node('p','저장된 대화가 없습니다.','hint'));return list}
function chatRender(chat){const log=$('#chat-log');clear(log);$('#chat-title').value=chat.title||'';
 if(!chat.messages.length)log.append(node('p','지금 프롬프트를 두고 대화합니다. 무엇이 이상한지 적으면 원인을 설명하고 고친 프롬프트를 제안합니다.','hint chat-empty'));
 for(const m of chat.messages){const bubble=node('div',null,'chat-msg '+m.role);
  if(m.role==='user'){bubble.append(node('div',m.content,'chat-text'))}
  else{bubble.append(node('div',m.explanation||m.content,'chat-text'));
   if(m.checks&&m.checks.length){const w=node('div',null,'chat-checks');w.append(node('strong','검사'));for(const c of m.checks)w.append(node('div',c));bubble.append(w)}
   if(m.prompt){const d=node('details');d.append(node('summary','제안된 프롬프트 보기'),node('pre',m.prompt,'prompt-dump'));bubble.append(d);
    const bar=node('div',null,'actions');const apply=node('button','이 프롬프트 적용','primary');
    apply.onclick=async()=>{S.previous=S.prompt;promptValue(m.prompt);$('#undo').disabled=false;if(typeof renderClipStatus==='function')renderClipStatus();
     await api(`/api/chats/${chat.id}/applied`,{prompt:m.prompt,label:(m.explanation||'').split(String.fromCharCode(10))[0].slice(0,50)});toast('프롬프트에 적용했습니다. 디렉터의 "이전 프롬프트"로 되돌릴 수 있습니다.')};
    bar.append(apply);bubble.append(bar)}}
  log.append(bubble)}
 if(chat.versions&&chat.versions.length){const v=node('details',null,'chat-versions');v.append(node('summary',`적용 기록 ${chat.versions.length}개`));
  chat.versions.slice().reverse().forEach(ver=>{const row=node('div',null,'chat-version');row.append(node('span',`${new Date(ver.at*1000).toLocaleTimeString(uiLocale())} · ${ver.label}`));
   const back=node('button','이 버전으로');back.onclick=()=>{S.previous=S.prompt;promptValue(ver.prompt);$('#undo').disabled=false;if(typeof renderClipStatus==='function')renderClipStatus();toast('그 버전으로 되돌렸습니다.')};row.append(back);v.append(row)});log.append(v)}
 log.scrollTop=log.scrollHeight}
async function chatOpen(id){chatId=id;const chat=await api('/api/chats/'+id);chatRender(chat);await chatList()}
async function chatStart(){const c=await api('/api/chats',{title:'새 대화',prompt:S.prompt||''});await chatOpen(c.id)}
action($('#chat-open'),async()=>{$('#chat-modal').hidden=false;renderChatSettings();const list=await chatList();if(chatId)await chatOpen(chatId);else if(list.length)await chatOpen(list[0].id);else await chatStart();$('#chat-message').focus()});
action($('#chat-close'),async()=>{$('#chat-modal').hidden=true});
action($('#chat-new'),chatStart);
action($('#chat-delete'),async()=>{if(!chatId||!uiConfirm('이 대화를 삭제할까요?'))return;await api(`/api/chats/${chatId}/delete`,{});chatId='';const list=await chatList();if(list.length)await chatOpen(list[0].id);else await chatStart()});
$('#chat-title').addEventListener('change',async e=>{if(chatId){await api(`/api/chats/${chatId}/rename`,{title:e.target.value});chatList()}});
async function chatSend(){const text=$('#chat-message').value.trim();if(!text)return;if(!S.chat_llm?.model){toast('대화 LLM 설정에서 모델을 선택하세요.');$('#chat-llm-settings').open=true;return}if(!chatId)await chatStart();
 const btn=$('#chat-send');btn.disabled=true;btn.textContent='생각 중…';
 const log=$('#chat-log');const pending=node('div',null,'chat-msg user');pending.append(node('div',text,'chat-text'));log.append(pending);log.scrollTop=log.scrollHeight;
 try{const r=S.render;const d=await api(`/api/chats/${chatId}/send`,{message:text,prompt:S.prompt||'',llm:{...S.chat_llm},model:S.chat_llm.model,temperature:S.chat_llm.temperature,think:S.chat_llm.think,engine:r.engine,
   duration:r.engine==='continuum'?(r.chunk_seconds||5):(r.duration||5),render:{engine:r.engine,chunks:r.chunks,context_length:r.context_length,prompt_mode:r.prompt_mode,audio_continuity:r.audio_continuity,mode:r.mode,finish:r.finish}});
  $('#chat-message').value='';chatRender(d.chat);chatList()}
 catch(e){pending.remove();toast(e.message)}finally{btn.disabled=false;btn.textContent='보내기'}}
action($('#chat-send'),chatSend);
$('#chat-message').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();chatSend()}});

initI18n().catch(error=>console.error('UI language:',error));
